def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    winners_est = int(supply / WATER_REQ)
    if winners_est < 1:
        winners_est = 1

    prev_bids = []
    prev_max = 0.0
    prev_min = None
    urgent_opp = 0
    rich_opp = 0

    for opp in alive_opponents:
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid > prev_max:
                    prev_max = bid
                if prev_min is None or bid < prev_min:
                    prev_min = bid

    if prev_min is None:
        prev_min = DAILY_SALARY * 0.5

    need_level = 0
    if hp <= 2 or no_water_days >= 2:
        need_level = 3
    elif hp <= 4 or no_water_days >= 1:
        need_level = 2
    elif hp <= 6:
        need_level = 1

    if not alive_opponents:
        if need_level >= 2:
            return min(budget, DAILY_SALARY * 0.55)
        return min(budget, DAILY_SALARY * 0.2)

    pressure = prev_max
    if urgent_opp >= 2:
        pressure += 6
    elif urgent_opp == 1:
        pressure += 3

    if winners_est >= 2:
        if need_level == 0:
            bid = max(18.0, prev_min * 0.72)
        elif need_level == 1:
            bid = max(32.0, prev_min * 0.9)
        elif need_level == 2:
            bid = max(52.0, min(pressure * 0.82, DAILY_SALARY * 0.95))
        else:
            bid = max(68.0, min(pressure + 2.0, budget))
    else:
        if need_level == 0:
            bid = max(24.0, min(prev_min * 0.85, DAILY_SALARY * 0.55))
        elif need_level == 1:
            bid = max(45.0, min(pressure * 0.72, DAILY_SALARY * 0.85))
        elif need_level == 2:
            bid = max(65.0, min(pressure * 0.9 + 2.0, budget))
        else:
            bid = max(78.0, min(pressure + 4.0, budget))

    if day >= 8 and budget > DAILY_SALARY * 2:
        bid += 4.0
    if rich_opp >= 2 and need_level >= 2:
        bid += 3.0
    if hp >= 8 and no_water_days == 0 and winners_est >= 2:
        bid *= 0.9

    max_safe = budget
    if need_level == 0:
        max_safe = min(max_safe, budget * 0.45)
    elif need_level == 1:
        max_safe = min(max_safe, budget * 0.6)
    elif need_level == 2:
        max_safe = min(max_safe, budget * 0.8)

    bid = min(bid, max_safe)
    if need_level >= 2:
        bid = max(bid, 50.0)
    elif need_level == 1:
        bid = max(bid, 28.0)
    else:
        bid = max(bid, 12.0)

    if bid > budget:
        bid = budget
    if bid < 0:
        bid = 0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', True)]
    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if not opp.get('alive', True):
            continue
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many units of water are likely needed per winner.
    # In this game, each unit of water corresponds to meeting WATER_REQ hp impact.
    # Use supply to gauge competition intensity.
    supply_units = max(0.0, supply / float(WATER_REQ))

    # Base willingness: if supply is scarce, bid more; if plentiful, bid less.
    # Normalize scarcity between MIN_SUPPLY and MAX_SUPPLY.
    if MAX_SUPPLY != MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        scarcity = 0.5
    scarcity = max(0.0, min(1.0, scarcity))

    # Pressure from opponents: if yesterday someone bid very high, expect aggressive competition.
    pressure = 0.0
    if max_prev_bid >= DAILY_SALARY * 1.20:
        pressure = 1.0
    elif max_prev_bid >= DAILY_SALARY * 0.95:
        pressure = 0.7
    elif max_prev_bid >= DAILY_SALARY * 0.75:
        pressure = 0.4

    # Decide target bid based on our hp/no_water_days and observed pressure.
    # If we're in danger, overbid to secure water.
    if hp <= 2 or no_water_days >= 2:
        target = DAILY_SALARY * (0.95 + 0.25 * pressure)
    elif hp == 3:
        target = DAILY_SALARY * (0.70 + 0.20 * pressure)
    else:
        # hp >= 4
        target = DAILY_SALARY * (0.55 + 0.25 * scarcity + 0.15 * pressure)

    # Convert target into an absolute bid cap.
    # Keep within budget and avoid extreme overbids.
    # Also slightly anchor relative to max_prev_bid to beat typical aggressive bids.
    if max_prev_bid > 0:
        # If pressure is high, try to be competitive but not necessarily the top.
        if pressure >= 0.7:
            target = max(target, max_prev_bid * 0.88)
        elif pressure >= 0.4:
            target = max(target, max_prev_bid * 0.75)

    # Final clamp
    bid = float(target)
    bid = max(0.0, min(budget, bid))

    # Small deterministic jitter to avoid ties (still safe)
    jitter = ((day * 37) % 10) * 0.3
    bid = min(budget, bid + jitter)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids)

    # If supply is tight, bid aggressively to ensure survival
    if supply < 18:
        bid = min(my_status['budget'], avg_opp_bid * 1.1)
    # If supply is generous, bid moderately
    else:
        bid = min(my_status['budget'], avg_opp_bid * 0.95)

    # Desperation logic if HP is low
    if my_status['hp'] <= 2:
        bid = min(my_status['budget'], DAILY_SALARY * 1.2)

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']
    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    last_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            last_bids.append(trace['bid'])
    portions = supply // WATER_REQ
    if hp <= 2 or no_water >= 1:
        if last_bids:
            target = max(last_bids) * 1.1
        else:
            target = DAILY_SALARY * 0.9
        target = min(target, budget * 0.9)
        return max(1, target)
    elif hp <= 4:
        if last_bids:
            target = max(last_bids) * 0.95
        else:
            target = DAILY_SALARY * 0.6
        if portions <= 1:
            target *= 1.2
        return min(budget, max(1, target))
    else:
        if portions >= 3:
            return DAILY_SALARY * 0.3
        else:
            if last_bids:
                target = max(last_bids) * 0.8
            else:
                target = DAILY_SALARY * 0.4
            return min(budget, max(1, target))
